{"check_build": {"code": "script({title:"Imperial Star Destroyer",palette:{hull:"light bluish grey",dark:"dark bluish grey",glow:"trans light blue"}});
const L=96,N=L/2;
const hw=z=>Math.round((z+4)*0.3);
const layers=[[14,3,9],[17,3,6],[20,3,3],[23,3,0],[29,2,0],[31,2,2],[33,2,4],[35,2,6],[37,2,8],[39,2,10],[41,2,12],[43,4,14],[47,3,18]];
const hullOps=[],trenchOps=[],greebleOps=[],ridgeOps=[];
const gp=["grille","round","cheese","tile","tile2"];
for(let i=0;i<N;i++){const z=2*i,h=hw(z+2);let topY=0;
 for(const [y,hh,d] of layers){const half=h-d;if(half<1)continue;
  hullOps.push(box({at:[-half,y,z],size:[2*half,hh,2],colour:"hull",top:"tile",interior:"solid"}));
  if(d<14)topY=y+hh;
  if(y>=31&&d>=2&&half>=3&&z<92&&!(d===12&&z>=58)&&rng()<0.6){
   const k=gp[Math.floor(rng()*gp.length)];const yt=y+hh;
   const xr=k==="round"||k==="tile"?half-1:half-2;const xl=-half+(k==="round"||k==="tile"?0:1);
   const mk=(x,turnR)=>{if(k==="grille")return place({part:"2412b",at:[x,yt,z],colour:"dark",turn:90});
    if(k==="round")return place({part:"6141",at:[x,yt,z],colour:"dark"});
    if(k==="cheese")return place({part:"54200",at:[x,yt,z],colour:"hull",turn:turnR});
    if(k==="tile")return place({part:"3070b",at:[x,yt,z],colour:"dark"});
    return place({part:"3069b",at:[x,yt,z],colour:"hull",turn:90});};
   greebleOps.push(mk(xr,270),mk(xl,90));}
 }
 const th=h-1;
 if(th>=1){if(th>=4){trenchOps.push(box({at:[-th+2,26,z],size:[2*th-4,3,2],colour:"dark",interior:"solid"}),box({at:[-th,26,z],size:[2,3,2],colour:"dark",texture:"grille"}),box({at:[th-2,26,z],size:[2,3,2],colour:"dark",texture:"grille"}));}else trenchOps.push(box({at:[-th,26,z],size:[2*th,3,2],colour:"dark",interior:"solid"}));}
 if(z<46&&topY>0&&h>=2)ridgeOps.push(box({at:[-1,topY,z],size:[2,2,2],colour:"hull",top:"tile",interior:"solid"}));
}
section("Hull",hullOps);
section("Trench",trenchOps);
section("Ridge",ridgeOps);
section("Greebles",greebleOps);
const turrets=[];
for(const z of [60,68,76,84,92]){const h=hw(z+2);if(hw(z+4)!==h)continue;const x=h-14;
 turrets.push(place({part:"4032b",at:[x,43,z],colour:"hull"}),place({part:"4740",at:[x,44,z],colour:"dark"}),place({part:"4032b",at:[-x-2,43,z],colour:"hull"}),place({part:"4740",at:[-x-2,44,z],colour:"dark"}));}
section("Turrets",turrets);
section("Tower",[
 box({at:[-5,50,78],size:[10,12,14],colour:"hull",top:"tile"}),
 box({at:[-11,62,80],size:[22,6,10],colour:"hull",top:"tile"}),
 dome({at:[-9,68,83],diameter:4,colour:"white"}),dome({at:[5,68,83],diameter:4,colour:"white"}),
 box({at:[-1,68,84],size:[2,6,2],colour:"dark",interior:"solid"}),
 place({part:"3957a",at:[0,74,84],colour:"dark"}),
 place({part:"4740",at:[-1,50,70],colour:"dark"}),
 ...[72,74].flatMap(z=>[place({part:"2412b",at:[-7,50,z],colour:"dark"}),place({part:"2412b",at:[5,50,z],colour:"dark"})])
]);
const engine=(cx,cy,big)=>big?[
 box({at:[cx-3,cy,94],size:[6,6,6],colour:"glow",interior:"solid"}),
 box({at:[cx-4,cy-2,94],size:[8,2,6],colour:"dark",interior:"solid"}),
 box({at:[cx-4,cy+6,94],size:[8,2,6],colour:"dark",interior:"solid"}),
 box({at:[cx-4,cy,94],size:[1,6,6],colour:"dark",interior:"solid"}),
 box({at:[cx+3,cy,94],size:[1,6,6],colour:"dark",interior:"solid"})]:[
 box({at:[cx-1,cy,95],size:[2,4,4],colour:"glow",interior:"solid"}),
 box({at:[cx-2,cy-1,95],size:[4,1,4],colour:"dark",interior:"solid"}),
 box({at:[cx-2,cy+4,95],size:[4,1,4],colour:"dark",interior:"solid"}),
 box({at:[cx-2,cy,95],size:[1,4,4],colour:"dark",interior:"solid"}),
 box({at:[cx+1,cy,95],size:[1,4,4],colour:"dark",interior:"solid"})];
section("Engines",[...engine(-14,25,true),...engine(0,25,true),...engine(14,25,true),...engine(-24,26,false),...engine(24,26,false)]);
section("Stand",[
 floor({at:[-10,0,50],size:[20,16],layers:2,colour:"black",top:"tile"}),
 box({at:[-3,2,54],size:[6,9,8],colour:"dark",interior:"solid"}),
 box({at:[-6,11,46],size:[12,3,24],colour:"dark",interior:"solid"})
]);", "seed": 1}}

